    {
        LLVOAvatar* av = LLDirectorCast::instance().resolve(entry.first);
        stopDirectorTurnAnimation(av, entry.second);
        restoreDirectorLookAtPose(av, entry.second);
    }
    mDirectorGazes.clear();
    mGazeCuePreviews.clear();
}

